/// A property as the shipped scenes actually set it.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct PropertyUsage {
    /// Property name.
    pub name: &'static str,
    /// How many times an author set it explicitly.
    pub times_set: u32,
    /// Lowest value seen, for numeric properties.
    pub low: Option<f64>,
    /// Middle value seen, for numeric properties: what to aim at without other guidance.
    pub median: Option<f64>,
    /// Highest value seen, for numeric properties.
    pub high: Option<f64>,
    /// Most frequent value, for properties that are not numeric.
    pub most_common: Option<&'static str>,
}

