/// A node or modifier property as declared by the installed build.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct NodeProperty {
    /// Property name as it appears in the serialized node.
    pub name: &'static str,
    /// Declared .NET type, useful for reporting and for enum-valued properties.
    pub cs_type: &'static str,
    /// Default from [Parameter], when the attribute carried a (default, min, max) triple.
    pub default_value: Option<f64>,
    /// Lower bound, when known.
    pub min: Option<f64>,
    /// Upper bound, when known.
    pub max: Option<f64>,
    /// Label shown in the Gaea interface, when it differs from the serialized name.
    /// Multiplier.Value, for one, is presented as "Height Remap".
    pub label: Option<&'static str>,
    /// Default for a property that is not numeric: an enumeration member, or true/false.
    pub default_text: Option<&'static str>,
    /// Curve exponent, when the property moves non-linearly under its slider. A curved
    /// property set to half its range is not half its effect.
    pub curve: Option<f64>,
}

